"""Forecast family: AFTS 13, trend following with a volatility-regime multiplier: the AFTS 9 mix times 2 down to 0.5 as volatility rises against the last 1000 candles. Enters long above a forecast of 0, leaves at or under it; stake cut to a 40% vol target and sized by the forecast over 10."""

from pandas import DataFrame

from freqtrade.strategy import IStrategy
from lab import channels, forecasts


class CarverRegimeMix_4h(IStrategy):
    INTERFACE_VERSION = 3
    timeframe = "4h"
    can_short = False
    startup_candle_count = 1300
    minimal_roi = {"0": 100}
    stoploss = -0.1225

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe["forecast"] = forecasts.regime_mix(dataframe["close"], fasts=[8, 16, 32, 64], fdm=1.13, history=1000)
        dataframe["scale"] = channels.vol_scale(dataframe["close"], 0.4, 30, 2190)
        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[(dataframe["forecast"] > 0) & dataframe["scale"].notna() & (dataframe["volume"] > 0), "enter_long"] = 1
        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[dataframe["forecast"] <= 0, "exit_long"] = 1
        return dataframe

    def custom_stake_amount(self, pair: str, current_time, current_rate, proposed_stake, min_stake, max_stake,
                            leverage, entry_tag, side, **kwargs) -> float:
        """The proposed stake times the vol scale and, unless the rule sizes flat, the forecast over its average of 10."""
        df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
        if df.empty:
            return proposed_stake
        last = df.iloc[-1]
        weight = min(max(float(last["forecast"]) / 10.0, 0.0), 1.0)
        return min(max(proposed_stake * float(last["scale"]) * weight, min_stake or 0.0), max_stake)
